mapper.select:
SELECT d.doc_id, d.title, d.type, d.creator_name,
       d.last_editor_name, d.current_version, d.word_count,
       d.edit_count, d.view_count, d.tags, IF(f.user_id IS NULL, 0, 1) AS is_favorite,
       d.create_time, d.last_edit_time, d.folder_id, IF(p.user_id IS NULL,0,1) AS is_pinned,
       (SELECT COUNT(*) FROM doc_member m WHERE m.doc_id = d.doc_id) as member_count,
       (SELECT COUNT(*) FROM doc_member m WHERE m.doc_id = d.doc_id AND m.is_online = 1) as online_member_count
FROM doc_document d
LEFT JOIN doc_user_favorite f ON f.doc_id=d.doc_id AND f.user_id=#{request.userId}
LEFT JOIN doc_user_pin p ON BINARY p.doc_id=BINARY d.doc_id AND p.user_id=#{request.userId}
WHERE d.deleted = 0 AND d.status = #{request.status}
AND d.creator_id=#{request.userId}
AND d.creator_id=#{request.userId}
AND d.creator_id != #{request.userId}
AND f.user_id IS NOT NULL

    AND d.space_id = #{request.spaceId}


    AND d.type = #{request.type}


    AND d.folder_id = #{request.folderId}


    AND d.title LIKE CONCAT('%', #{request.keyword}, '%')


    AND d.tags LIKE CONCAT('%', #{request.tag}, '%')

ORDER BY is_pinned DESC, d.last_edit_time DESC, d.create_time DESC
